// Deferred model-facing reference. No imports, runtime access, or installation effects.
export const COMPONENT_CATALOG = {
  Card: { description: 'Bordered inner content section. Default slot; optional heading.', props: ['title'], example: '<Card title="Overview"><p>Trusted Vue content</p></Card>' },
  Row: { description: 'Wrapping horizontal layout; default slot.', props: [], example: '<Row><Stat label="Open" :value="4"/><Stat label="Done" :value="12"/></Row>' },
  Columns: { description: 'Responsive equal-width grid; count 1–6, default 2; one column on narrow screens.', props: ['count'], example: '<Columns :count="2"><Card title="Left"/><Card title="Right"/></Columns>' },
  Tabs: { description: 'Accessible arrow/Home/End tab navigation; direct Tab children (including v-for fragments). Selection persists in draft.tabs by id. Give each Tabs a stable unique id; Vue.useId is the fallback. Selection never sends a reply.', props: ['id', 'label'], example: '<Tabs id="overview" label="Overview"><Tab name="summary" label="Summary"><p>Summary</p></Tab><Tab name="details" label="Details"><p>Details</p></Tab></Tabs>' },
  Tab: { description: 'Child of Tabs with default content slot. Unique name recommended; label falls back to name. Disabled tabs are skipped by keyboard navigation.', props: ['name', 'label', 'disabled'], example: '<Tab name="details" label="Details"><p>Panel content</p></Tab>' },
  Stat: { description: 'Labeled scalar statistic; optional hint.', props: ['label', 'value', 'hint'], example: '<Stat label="Revenue" :value="1200" hint="This month"/>' },
  Chips: { description: 'Read-only list of scalar labels or objects with label; no implicit selection/send.', props: ['items'], example: '<Chips :items="[\'Vue\', \'Local\', \'Trusted\']"/>' },
  Progress: { description: 'Native accessible progress indicator; defaults value=0, max=100. Supply a descriptive label.', props: ['value', 'max', 'label'], example: '<Progress label="Complete" :value="65" :max="100"/>' },
  Steps: { description: 'Read-only ordered steps with aria-current. Current is a zero-based index. Items are labels or {label}.', props: ['items', 'current'], example: '<Steps :items="[\'Choose\', \'Review\', \'Send\']" :current="1"/>' },
  Table: { description: 'Local search and column-button sort; typed columns [{key,label}], up to first 500 rows. rowKey defaults to id: unique stable scalar ids strongly recommended; missing keys fall back to original array index. selectable enables checkboxes; modelValue is selected row keys, emitting update:modelValue. Selection is local unless sendSelection adds an explicit send button, which replies {selection:[keys]}. No send on row selection. Search/sort never send a reply.', props: ['columns', 'rows', 'rowKey', 'caption', 'searchable', 'selectable', 'modelValue', 'sendSelection', 'sendLabel'], example: '<Table :columns="[{key:\'name\',label:\'Name\'},{key:\'score\',label:\'Score\'}]" :rows="[{id:1,name:\'Ada\',score:9}]" caption="Results" selectable v-model="chosen"/>' },
  Bars: { description: 'Accessible horizontal SVG bars from supplied [{label,value}], including negative values. First 200 points; non-finite/non-number values become 0. Includes title/description and expandable data table. No network access.', props: ['data', 'title', 'description'], example: '<Bars title="Sales" description="Quarterly totals" :data="[{label:\'Q1\',value:12},{label:\'Q2\',value:18}]"/>' },
  Line: { description: 'Accessible SVG line from supplied [{label,value}], including negative values; first 200 points. Non-finite/non-number values become 0. Includes visible caption, description and expandable data table.', props: ['data', 'title', 'description'], example: '<Line title="Trend" :data="[{label:\'Mon\',value:3},{label:\'Tue\',value:8}]"/>' },
  Donut: { description: 'Accessible SVG donut from supplied [{label,value}], first 200 points. Negative contributions clamp to zero in geometry; table preserves signed values. Zero total renders an empty track. Three repeating theme-token colors; table identifies every segment.', props: ['data', 'title', 'description'], example: '<Donut title="Share" :data="[{label:\'A\',value:30},{label:\'B\',value:70}]"/>' },
  Field: { description: 'Standalone v-model, or a named field inside Form using injected values/errors. Supported type: text, textarea, number, slider, select, radio, checks, switch, date, time, segmented. Options are string/number/boolean primitives or {label,value} objects; scalar value types are preserved. Primitive labels are String(value). hint falls back to description for visible and accessible help; placeholder applies to inputs/textarea and the select empty caption. checks stores an array, switch a boolean, number/slider a number or null. Supply metadata explicitly for custom slotted fields; automatic Form rendering uses the full schema. min/max/step numeric; minLength/maxLength constrain text. Validation is supplied by the parent context, not this component.', props: ['name', 'type', 'label', 'hint', 'description', 'placeholder', 'modelValue', 'required', 'disabled', 'options', 'min', 'max', 'step', 'minLength', 'maxLength'], example: '<Field v-model="amount" type="number" label="Amount" :min="0" :step="0.5" required/>' },
  Form: { description: 'Authoritative fields default to context.fields.value; custom fields may be passed. Schema: {name,type,label,hint,description,placeholder,initial,required,disabled,options,min,max,step,minLength,maxLength}; options contain string/number/boolean primitives or {label,value} objects. One shared persisted draft.form object per reply; initializes schema initial values, saved draft, then submitted.values. Default content auto-renders fields; optional scoped default slot receives {values,errors,submit,reset}. Automatic actions default true. Preset and reset are local-only. Submit clones JSON values, omits optional unset numeric null and unmatched choice empty-string sentinels (also optional empty text with minLength>0), calls context.validateFields(fields,values), then context.reply(values,humanSummary). Required invalid values remain errors. summary overrides the generated labeled summary; all send summaries cap at 2000 characters. Readonly/submitted locks edits and sends. No nested forms.', props: ['fields', 'preset', 'summary', 'actions', 'submitLabel', 'resetLabel', 'presetLabel'], example: '<Form :preset="{name:\'Ada\'}"/>' },
  Button: { description: 'Native button, type button by default; type submit/reset uses surrounding HTML Form semantics. Default slot supplies label; emits click. Does not send by default. Explicit send replies with JSON-cloned value (default {}) and optional summary on click only; pending/readonly/submitted disables. A click handler can preventDefault to cancel send.', props: ['type', 'send', 'value', 'summary', 'disabled'], example: '<Button send :value="{choice:\'yes\'}" summary="Yes">Confirm</Button>' },
};

export function catalogGuide(name) {
  const intro = 'Trusted Vue/JS reply catalog (render functions; no external libraries/network). Components are optional: custom Vue/JS remains allowed. Field edits, tabs, table sort/search/selection and form reset/preset are local; only Form submit, Button send, or Table sendSelection explicitly reply. Readonly/submitted locks edits/sends. Table ≤500 rows; charts ≤200 points. One shared draft.form per reply. Use stable Tabs id and unique Table row ids. Fetch one component by exact name for props and example.';
  if (name === undefined || name === '') return `${intro}\nComponents: ${Object.keys(COMPONENT_CATALOG).join(', ')}.`.slice(0, 1800);
  const entry = Object.hasOwn(COMPONENT_CATALOG, name) ? COMPONENT_CATALOG[name] : null;
  if (!entry) return `Unknown component ${String(name).slice(0, 100)}. Available: ${Object.keys(COMPONENT_CATALOG).join(', ')}.`;
  return `${name}: ${entry.description}\nProps: ${entry.props.join(', ') || '(none)'}.\nExample: ${entry.example}`.slice(0, 4000);
}
